import re
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from collections import defaultdict

LAYER_HEIGHT = 0.2

def parse_gcode(filepath):
    moves = []  # list of (x, y, z, e_extruding, object_id)
    x, y, z, e = 0.0, 0.0, 0.0, 0.0
    current_object = 0  # 0=off, 1=text, 2=box
    obj_names = {0: 'none', 1: 'Embossed text', 2: 'Shape-Box'}

    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            # M486 marker
            m = re.match(r'^M486\s+S([-0-9.]+)', line)
            if m:
                v = int(float(m.group(1)))
                if v == 0:
                    current_object = 1   # Embossed text
                elif v == 1:
                    current_object = 2   # Shape-Box
                elif v == -1:
                    current_object = 0
                continue
            if line.startswith('G1') or line.startswith('G0'):
                params = line.split()
                new_x, new_y, new_z, new_e = x, y, z, e
                for p in params[1:]:
                    if p.startswith('X'):
                        new_x = float(p[1:])
                    elif p.startswith('Y'):
                        new_y = float(p[1:])
                    elif p.startswith('Z'):
                        new_z = float(p[1:])
                    elif p.startswith('E'):
                        new_e = float(p[1:])
                e_extruding = new_e - e
                x, y, z, e = new_x, new_y, new_z, new_e
                if line.startswith('G1') and e_extruding > 0.0001:
                    moves.append((x, y, z, current_object))
    return moves

moves = parse_gcode('/app/text.gcode')
print(f"Total extrusion moves: {len(moves)}")

# Layer resolution
zs = np.array([m[2] for m in moves])
print(f"Z range: {zs.min():.2f} to {zs.max():.2f}")
print(f"Z unique count (rounded): {len(set(round(z,2) for z in zs))}")

# Count per object
obj_counts = defaultdict(int)
for m in moves:
    obj_counts[m[3]] += len(moves)
for obj_id, count in obj_counts.items():
    print(f"Object {obj_id}: count")

# Plot per layer
obj_counts = defaultdict(int)
for m in moves:
    obj_counts[m[3]] += 1
for obj_id, count in obj_counts.items():
    print(f"Object {obj_id}: {count} moves")

# Find which layers have what object
layer_objects = defaultdict(set)
for x, y, z, oid in moves:
    layer = int(round(z / LAYER_HEIGHT))
    layer_objects[layer].add(oid)

print(f"\nTotal layers: {max(layer_objects.keys())}")
print(f"Layer objects summary:")
for layer in sorted(layer_objects.keys()):
    objs = layer_objects[layer]
    if len(objs) > 1:
        print(f"Layer {layer} (z={layer*LAYER_HEIGHT:.2f}): {objs}")
    elif 0 in objs:
        print(f"Layer {layer} (z={layer*LAYER_HEIGHT:.2f}): off")

