# Show segment at specific Z layers
def render_layer_z(moves, target_z, xmin=0, xmax=250, ymin=0, ymax=210, filename='/tmp/slice.txt'):
    """Show the bounding box of motion at a specific Z layer"""
    segs = []
    for s in moves:
        (p0, p1, z) = s
        if abs(z - target_z) < 0.01:
            segs.append(s)
    if not segs:
        print(f"No segments at z={target_z}")
        return
    xs = []
    ys = []
    for (p0, p1, z) in segs:
        xs.extend([p0[0], p1[0]])
        ys.extend([p0[1], p1[1]])
    if xmin is None:
        xmin, xmax = min(xs), max(xs)
    if ymin is None:
        ymin, ymax = min(ys), max(ys)
    print(f"Z={target_z}: X={xmin:.2f}..{xmax:.2f}, Y={ymin:.2f}..{ymax:.2f}, segs={len(segs)}")

    width = 200
    aspect = (xmax - xmin) / max(1e-6, (ymax - ymin))
    height = max(30, int(width / (aspect * 2)))
    grid = [[' '] * width for _ in range(height)]

    pix = set()
    for (p0, p1, z) in segs:
        x0, y0 = p0
        x1, y1 = p1
        steps = max(2, int(max(abs(x1-x0), abs(y1-y0)) * 3))
        for t in range(steps + 1):
            f = t / steps
            xt = x0 + f * (x1 - x0)
            yt = y0 + f * (y1 - y0)
            col = int((xt - xmin) / (xmax - xmin) * (width - 1))
            row = int((1 - (yt - ymin) / (ymax - ymin)) * (height - 1))
            if 0 <= col < width and 0 <= row < height:
                pix.add((row, col))

    for (row, col) in pix:
        grid[row][col] = '#'
    print(''.join(['#' if any(c == '#' for c in row) else ' ' for row in grid]))
    with open(filename, 'w') as f:
        for row in grid:
            f.write(''.join(row) + '\n')
    print(f"Saved {filename}"


